nginx_conf:
worker_processes auto;
worker_rlimit_nofile 65535;
events {
    worker_connections 16384;
    use epoll;
    multi_accept on;
}
http {
    # USUNIĘTO limit_req_zone oraz limit_conn_zone

    log_format json_ml_format escape=json
    '{'
        '"timestamp":"$time_iso8601",'
        '"client_ip":"$remote_addr",'
        '"request_method":"$request_method",'
        '"request_uri":"$request_uri",'
        '"status":$status,'
        '"request_time":$request_time,'
        '"request_length":$request_length,'
        '"bytes_sent":$bytes_sent,'
        '"user_agent":"$http_user_agent"'
    '}';

    access_log /var/tmp/ddos_campaigns/drift_20261108/drift/attack_costly_search_flood/U/nginx_access.log json_ml_format;
    error_log /var/tmp/ddos_campaigns/drift_20261108/drift/attack_costly_search_flood/U/nginx_error.log info;

    # Phase P1 (docs/L7_GRU_DESIGN.md §3): same extended L7 request log as nginx.conf,
    # so captures and evaluation runs are schema-identical across modes. This mode has
    # no limit_req/limit_conn, so "lreq"/"lconn" are empty here — still valid JSON.
    log_format l7json escape=json
    '{'
        '"msec":$msec,'
        '"ip":"$remote_addr",'
        '"port":$remote_port,'
        '"conn":$connection,'
        '"creq":$connection_requests,'
        '"proto":"$server_protocol",'
        '"tls":"$ssl_protocol",'
        '"reused":"$ssl_session_reused",'
        '"method":"$request_method",'
        '"uri":"$request_uri",'
        '"status":$status,'
        '"compl":"$request_completion",'
        '"rt":$request_time,'
        '"uct":"$upstream_connect_time",'
        '"urt":"$upstream_response_time",'
        '"rlen":$request_length,'
        '"bsent":$bytes_sent,'
        '"lreq":"$limit_req_status",'
        '"lconn":"$limit_conn_status",'
        '"ua":"$http_user_agent"'
    '}';
    # The datagram-socket sink for this format is NOT part of the default config (audit
    # G-23): with no daemon bound to the socket, nginx logs "[warn] send() to syslog failed
    # while logging request" for every request. This conf is served only with
    # MITIGATION_MODE=none, where no daemon runs, so no runner adds the sink here; the marker
    # line below keeps it in step with nginx.conf, where capture_l7.render_l7_sink() writes
    # it for the runners that start the daemon with L7_SHADOW=1 (docs/L7_GRU_DESIGN.md, 4.3).
    # L7-SYSLOG-SINK

    client_body_timeout 5s;
    client_header_timeout 5s;
    keepalive_timeout 15s;
    send_timeout 10s;

    client_max_body_size 64k;
    large_client_header_buffers 2 1k;

    server {
        listen 80;
        listen 443 ssl;
        http2 on;
        server_name twojadomena.pl localhost;

        ssl_certificate /etc/ssl/certs/nginx-selfsigned.crt;
        ssl_certificate_key /etc/ssl/private/nginx-selfsigned.key;

        ssl_protocols TLSv1.2 TLSv1.3;
        ssl_prefer_server_ciphers on;

        ssl_session_cache shared:SSL:10m;
        ssl_session_timeout 10m;

        location / {
            # USUNIĘTO limit_req oraz limit_conn

            proxy_pass http://127.0.0.1:8080;

            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;

            proxy_connect_timeout 5s;
            proxy_send_timeout 10s;
            proxy_read_timeout 10s;
        }
    }
}
